/bin/bash -lc "find / -type f \\( -name pvpython -o -name paraview \\) -perm -111 2>/dev/null | head -30; find / -iname '*ttk*' -type f 2>/dev/null | head -40; python - <<'PY'
try:
 import vtk; print('vtk', vtk.vtkVersion.GetVTKVersion())
except Exception as e: print('no vtk',e)
try:
 import ot; print('ot', ot.__version__)
except Exception as e: print('no ot',e)
PY"

