/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
print([x for x in globals() if 'Persistence' in x or 'Tracking' in x or 'Morse' in x])
for n in ['TTKPersistenceDiagram','TTKPersistenceDiagramClustering','TTKTrackingFromPersistenceDiagrams','TTKTopologicalSimplification','TTKIdentifierRandomizer']:
 c=globals().get(n); print('\\n',n,c)
 if c:
  try:
   x=c(); print(x.ListProperties())
  except Exception as e: print(e)
PY"

